1231	// resetTransportAndUnlock unconditionally connects the addrConn.
1232	//
1233	// ac.mu must be held by the caller, and this function will guarantee it is released.
1234	func (ac *addrConn) resetTransportAndUnlock() {
1235		acCtx := ac.ctx
1236		if acCtx.Err() != nil {
1237			ac.mu.Unlock()
1238			return
1239		}
1240	
1241		addrs := ac.addrs
1242		backoffFor := ac.dopts.bs.Backoff(ac.backoffIdx)
1243		// This will be the duration that dial gets to finish.
1244		dialDuration := minConnectTimeout
1245		if ac.dopts.minConnectTimeout != nil {
1246			dialDuration = ac.dopts.minConnectTimeout()
1247		}
1248	
1249		if dialDuration < backoffFor {
1250			// Give dial more time as we keep failing to connect.
1251			dialDuration = backoffFor
1252		}
1253		// We can potentially spend all the time trying the first address, and
1254		// if the server accepts the connection and then hangs, the following
1255		// addresses will never be tried.
1256		//
1257		// The spec doesn't mention what should be done for multiple addresses.
1258		// https://github.com/grpc/grpc/blob/master/doc/connection-backoff.md#proposed-backoff-algorithm
1259		connectDeadline := time.Now().Add(dialDuration)
1260	
1261		ac.updateConnectivityState(connectivity.Connecting, nil)
1262		ac.mu.Unlock()
1263	
1264		if err := ac.tryAllAddrs(acCtx, addrs, connectDeadline); err != nil {
1265			ac.cc.resolveNow(resolver.ResolveNowOptions{})
1266			ac.mu.Lock()
1267			if acCtx.Err() != nil {
1268				// addrConn was torn down.
1269				ac.mu.Unlock()
1270				return
1271			}
1272			// After exhausting all addresses, the addrConn enters
1273			// TRANSIENT_FAILURE.
1274			ac.updateConnectivityState(connectivity.TransientFailure, err)
1275	
1276			// Backoff.
1277			b := ac.resetBackoff
1278			ac.mu.Unlock()
1279	
1280			timer := time.NewTimer(backoffFor)
1281			select {
1282			case <-timer.C:
1283				ac.mu.Lock()
1284				ac.backoffIdx++
1285				ac.mu.Unlock()
1286			case <-b:
1287				timer.Stop()
1288			case <-acCtx.Done():
1289				timer.Stop()
1290				return
1291			}
1292	
1293			ac.mu.Lock()
1294			if acCtx.Err() == nil {
1295				ac.updateConnectivityState(connectivity.Idle, err)
1296			}
1297			ac.mu.Unlock()
1298			return
1299		}
1300		// Success; reset backoff.
1301		ac.mu.Lock()
1302		ac.backoffIdx = 0
1303		ac.mu.Unlock()
1304	}
