1518	// getTransport waits until the addrconn is ready and returns the transport.
1519	// If the context expires first, returns an appropriate status.  If the
1520	// addrConn is stopped first, returns an Unavailable status error.
1521	func (ac *addrConn) getTransport(ctx context.Context) (transport.ClientTransport, error) {
1522		for ctx.Err() == nil {
1523			ac.mu.Lock()
1524			t, state, sc := ac.transport, ac.state, ac.stateChan
1525			ac.mu.Unlock()
1526			if state == connectivity.Ready {
1527				return t, nil
1528			}
1529			if state == connectivity.Shutdown {
1530				return nil, status.Errorf(codes.Unavailable, "SubConn shutting down")
1531			}
1532	
1533			select {
1534			case <-ctx.Done():
1535			case <-sc:
1536			}
1537		}
1538		return nil, status.FromContextError(ctx.Err()).Err()
1539	}
