1541	// tearDown starts to tear down the addrConn.
1542	//
1543	// Note that tearDown doesn't remove ac from ac.cc.conns, so the addrConn struct
1544	// will leak. In most cases, call cc.removeAddrConn() instead.
1545	func (ac *addrConn) tearDown(err error) {
1546		ac.mu.Lock()
1547		if ac.state == connectivity.Shutdown {
1548			ac.mu.Unlock()
1549			return
1550		}
1551		curTr := ac.transport
1552		ac.transport = nil
